#nullable enable // autogenerated

using MVZ2Logic.Models.Elements;
using PVZEngine.Tools.Unity;
using UnityEngine;

namespace MVZ2.Models
{
    [DisallowMultipleComponent]
    public sealed class ModelBone : MonoBehaviour
    {
        public void SetLightVisible(bool visible)
        {
            if (lightController)
            {
                lightController.gameObject.SetActive(visible);
            }
        }
        public void SetLightColor(Color color)
        {
            if (lightController)
            {
                lightController.SetColor(color);
            }
        }
        public void SetLightRange(Vector2 range)
        {
            if (lightController)
            {
                lightController.SetRange(range);
            }
        }
        public void SetLightParent(Transform? parent)
        {
            if (lightController)
            {
                if (parent.Exists())
                {
                    lightController.transform.SetParent(parent);
                }
                else
                {
                    lightController.transform.SetParent(transform);
                }
            }
        }
        public void SetLightOffset(Vector3 offset)
        {
            if (lightController)
            {
                lightController.transform.localPosition = offset;
            }
        }
        [Header("Light")]
        [SerializeField]
        private LightController lightController = null!;
    }
}